class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.items:
            return None
        return self.items.pop()

    def peek(self):
        if not self.items:
            return None
        return self.items[-1]

    def is_empty(self):
        return len(self.items) == 0

def is_balanced(expression):
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = set(pairs.values())
    stack = Stack()
    for ch in expression:
        if ch in openers:
            stack.push(ch)
        elif ch in pairs:
            if stack.is_empty() or stack.pop() != pairs[ch]:
                return False
    return stack.is_empty()

print(is_balanced('((()))'))       # True
print(is_balanced('([{}])'))       # True
print(is_balanced('((())'))        # False
print(is_balanced('{[}]'))         # False
